    parcelLoadPromise = fetchJson(PARCELS_URL, { cache: "force-cache" })
      .then(geojson => {
        parcelFeatures = Array.isArray(geojson?.features) ? geojson.features : [];
      }).catch(err => {
        parcelLoadPromise = null;
        throw err;
      });
  }
